--
-- Table structure for table `salesreturnproducts`
--

DROP TABLE IF EXISTS `salesreturnproducts`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `salesreturnproducts` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `product_id` bigint(20) unsigned DEFAULT NULL,
  `unit_id` bigint(20) unsigned DEFAULT NULL,
  `count` bigint(20) unsigned DEFAULT NULL,
  `total` double NOT NULL DEFAULT '0',
  `expire_date` date DEFAULT NULL,
  `salesreturn_id` bigint(20) unsigned DEFAULT NULL,
  `patch_id` bigint(20) unsigned DEFAULT NULL,
  `pharmacy_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `salesreturnproducts_unit_id_foreign` (`unit_id`),
  KEY `salesreturnproducts_product_id_foreign` (`product_id`),
  KEY `salesreturnproducts_salesreturn_id_foreign` (`salesreturn_id`),
  KEY `salesreturnproducts_patch_id_foreign` (`patch_id`),
  KEY `salesreturnproducts_pharmacy_id_foreign` (`pharmacy_id`),
  CONSTRAINT `salesreturnproducts_patch_id_foreign` FOREIGN KEY (`patch_id`) REFERENCES `patches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `salesreturnproducts_pharmacy_id_foreign` FOREIGN KEY (`pharmacy_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE,
  CONSTRAINT `salesreturnproducts_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `salesreturnproducts_salesreturn_id_foreign` FOREIGN KEY (`salesreturn_id`) REFERENCES `salesreturns` (`id`) ON DELETE CASCADE,
  CONSTRAINT `salesreturnproducts_unit_id_foreign` FOREIGN KEY (`unit_id`) REFERENCES `units` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=179 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
