--
-- Table structure for table `salesreturns`
--

DROP TABLE IF EXISTS `salesreturns`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `salesreturns` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `reference_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_of_sale` date DEFAULT NULL,
  `salereturns_tax` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `invoiceTotal` double NOT NULL DEFAULT '0',
  `willPay` double NOT NULL DEFAULT '0',
  `debit` double NOT NULL DEFAULT '0',
  `branch_id` bigint(20) unsigned DEFAULT NULL,
  `admin_id` bigint(20) unsigned DEFAULT NULL,
  `sales_id` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `createdBy_id` bigint(20) unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `salesreturns_branch_id_foreign` (`branch_id`),
  KEY `salesreturns_admin_id_foreign` (`admin_id`),
  KEY `salesreturns_sales_id_foreign` (`sales_id`),
  KEY `salesreturns_createdby_id_foreign` (`createdBy_id`),
  CONSTRAINT `salesreturns_admin_id_foreign` FOREIGN KEY (`admin_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE,
  CONSTRAINT `salesreturns_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `salesreturns_createdby_id_foreign` FOREIGN KEY (`createdBy_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE,
  CONSTRAINT `salesreturns_sales_id_foreign` FOREIGN KEY (`sales_id`) REFERENCES `saless` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=130 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

