DROP TABLE IF EXISTS `saless`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `saless` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `reference_number` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `branch_id` bigint(20) unsigned DEFAULT NULL,
  `set_default_selling_prices` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `admin_id` bigint(20) unsigned DEFAULT NULL,
  `pharmacist_id` bigint(20) unsigned DEFAULT NULL,
  `is_pharmacist` tinyint(1) NOT NULL DEFAULT '0',
  `payment_period_number` int(11) DEFAULT NULL,
  `payment_period` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `date_of_sales` date DEFAULT NULL,
  `sales_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `discount_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `discount_value` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `saless_tax` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `notes` text COLLATE utf8mb4_unicode_ci,
  `shipping_details` text COLLATE utf8mb4_unicode_ci,
  `shipping_address` text COLLATE utf8mb4_unicode_ci,
  `shipping_fees` double DEFAULT NULL,
  `shipping_status` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `delivered_to` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `additional_account_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `invoiceTotal` double DEFAULT '0',
  `willPay` double NOT NULL DEFAULT '0',
  `debit` double NOT NULL DEFAULT '0',
  `paymentMethod_id` bigint(20) unsigned DEFAULT NULL,
  `seller_id` bigint(20) unsigned DEFAULT NULL,
  `qrcode_path` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `createdBy_id` bigint(20) unsigned NOT NULL DEFAULT '1',
  PRIMARY KEY (`id`),
  KEY `saless_branch_id_foreign` (`branch_id`),
  KEY `saless_admin_id_foreign` (`admin_id`),
  KEY `saless_pharmacist_id_foreign` (`pharmacist_id`),
  KEY `saless_paymentmethod_id_foreign` (`paymentMethod_id`),
  KEY `saless_seller_id_foreign` (`seller_id`),
  KEY `saless_createdby_id_foreign` (`createdBy_id`),
  CONSTRAINT `saless_admin_id_foreign` FOREIGN KEY (`admin_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE,
  CONSTRAINT `saless_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE,
  CONSTRAINT `saless_createdby_id_foreign` FOREIGN KEY (`createdBy_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE,
  CONSTRAINT `saless_paymentmethod_id_foreign` FOREIGN KEY (`paymentMethod_id`) REFERENCES `paymentMethods` (`id`) ON DELETE CASCADE,
  CONSTRAINT `saless_pharmacist_id_foreign` FOREIGN KEY (`pharmacist_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE,
  CONSTRAINT `saless_seller_id_foreign` FOREIGN KEY (`seller_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1377 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
