--
-- Table structure for table `seller_products`
--

DROP TABLE IF EXISTS `seller_products`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `seller_products` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `firstTake` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `take` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `price` double DEFAULT NULL,
  `seller_id` bigint(20) unsigned NOT NULL,
  `product_id` bigint(20) unsigned NOT NULL,
  `store_id` bigint(20) unsigned NOT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `seller_products_seller_id_foreign` (`seller_id`),
  KEY `seller_products_product_id_foreign` (`product_id`),
  KEY `seller_products_store_id_foreign` (`store_id`),
  CONSTRAINT `seller_products_product_id_foreign` FOREIGN KEY (`product_id`) REFERENCES `products` (`id`) ON DELETE CASCADE,
  CONSTRAINT `seller_products_seller_id_foreign` FOREIGN KEY (`seller_id`) REFERENCES `admins` (`id`) ON DELETE CASCADE,
  CONSTRAINT `seller_products_store_id_foreign` FOREIGN KEY (`store_id`) REFERENCES `stores` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

